/**
 * Minimal JSON body/response helpers for the plugin's host route, following
 * the describe-image route family's conventions: one strict bounded reader
 * and one JSON writer with family-default headers.
 * @module dsh-prompt-enhance/http
 */

import type { IncomingMessage, ServerResponse } from 'node:http'

/**
 * Read a request body of at most `maxBytes` and parse it as JSON.
 *
 * On overflow the throw leaves the `for await` loop, and closing that loop
 * closes the async iterator — which a Node Readable does by destroying itself.
 * The request is therefore destroyed and marked `aborted`, and the unread
 * remainder is never consumed. The response socket outlives it (measured on node
 * v24.21.0), so the caller can still be answered, but nothing ends the half-read
 * request on the connection's behalf: the 413 path has to declare
 * `connection: close` itself, or the socket stays open with no FIN until Node's
 * request timeout reaps it.
 * @throws {@link BodyTooLargeError} past the cap, or the JSON.parse error otherwise.
 */

/**
 * The request body exceeded the route's cap.
 *
 * A class, not a message: callers must be able to tell this apart from a parse
 * error without matching text, so re-wording the message here cannot silently
 * turn a 413 into a 422.
 */
export class BodyTooLargeError extends Error {
  /** Stable discriminant for `instanceof`-free checks across realms. */
  readonly code = 'body-too-large'

  constructor() {
    super('body too large')
    this.name = 'BodyTooLargeError'
  }
}

/**
 * The request body was not declared as JSON.
 *
 * A class rather than a status constant: the route maps this one to 415, and
 * every other read/parse failure to 422. Missing `Content-Type` counts as a
 * mismatch, not an omission — a browser form POST is exactly the request that
 * omits the JSON type while still carrying a body.
 */
export class UnsupportedMediaTypeError extends Error {
  /** Stable discriminant for `instanceof`-free checks across realms. */
  readonly code = 'unsupported-media-type'

  constructor() {
    super('unsupported media type')
    this.name = 'UnsupportedMediaTypeError'
  }
}

/**
 * Read a JSON request body, refusing anything past `maxBytes`.
 * @param req - the incoming request.
 * @param maxBytes - the cap in bytes.
 * @returns the parsed JSON body.
 * @throws {@link BodyTooLargeError} past the cap, or the JSON.parse error otherwise.
 */
export async function readBoundedJson(req: IncomingMessage, maxBytes: number): Promise<unknown> {
  // JSON only, declared or not: a request without the header is a form or a
  // raw client, and both are shapes this route does not serve.
  const contentType = req.headers['content-type']
  if (typeof contentType !== 'string' || !/^application\/(?:[a-z0-9!#$&^_.+-]+\+)?json\b/i.test(contentType.trim())) {
    throw new UnsupportedMediaTypeError()
  }
  const chunks: Buffer[] = []
  let size = 0
  for await (const chunk of req) {
    const buffer = chunk as Buffer
    size += buffer.length
    if (size > maxBytes) throw new BodyTooLargeError()
    chunks.push(buffer)
  }
  return JSON.parse(Buffer.concat(chunks).toString('utf8'))
}

/**
 * Write one JSON response with family-default headers. Responses are dynamic
 * per-request results and must never be cached.
 */
export function writeJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'referrer-policy': 'no-referrer',
    'cache-control': 'no-store',
  })
  res.end(JSON.stringify(body))
}

/**
 * Terminate a response exactly once, whether or not headers were already sent.
 *
 * A chunked response only reaches a whole-body reader (`response.text()`, a
 * curl, a proxy) once the terminating `0\r\n\r\n` arrives. Every path that
 * writes to a stream therefore owes it the same close, including the failure
 * path — an unterminated error response looks like a hang to everyone except
 * a browser that happens to act on the error frame and stop reading.
 *
 * Idempotent and non-throwing: a client that vanished mid-stream leaves a dead
 * socket where ending would throw, and that must never mask the real outcome.
 * @param res - the response to close.
 */
export function endResponse(res: ServerResponse): void {
  if (res.writableEnded || res.destroyed) return
  try {
    res.end()
  } catch {
    // Half-closed socket: there is nothing left to terminate.
  }
}
